// Brief del día para el canal de motos: categoría y formato al azar (sin repetir los recientes),
// origen/época sugerido y la lista de temas ya hechos (tabla motos_historial).
// Lo que ya funciona en el canal: motos de entrada y, sobre todo, la Yamaha MT-03 (escape, accesorios, comparativas).
const CENTRO = [
  'Yamaha MT-03: datos y verdades', 'MT-03 vs sus rivales (R3, Ninja 400, Duke 390, CB500F)',
  'Motos de entrada de 250 a 500 cc: qué elegir', 'Escapes y sonido: qué cambia de verdad',
  'Accesorios y mods útiles para motos de entrada', 'Consumo, costos y mantenimiento real de una moto de entrada',
];
const GENERAL = [
  'Récords de velocidad', 'Historia de marcas legendarias', 'Motos icónicas de la historia', 'Competición (MotoGP, Dakar, Superbike)',
  'Inventos y hitos técnicos', 'Motor y transmisión', 'Frenos y suspensión', 'Electrónica y seguridad (ABS, control de tracción)',
  'Motos eléctricas y tecnología nueva', 'Mitos de mantenimiento', 'Errores comunes al manejar', 'Combustible, aceite y neumáticos',
  '2 tiempos vs 4 tiempos', 'Clásicas vs modernas', 'Scooters vs motos de cambios', 'Off-road vs calle', 'Café racer y motos custom',
];
const CATEGORIAS = CENTRO.concat(GENERAL);
const FORMATOS = [
  'dato curioso poco conocido', 'mito vs realidad', 'cómo funciona, explicado simple', 'comparación cara a cara',
  'historia con un giro sorprendente', 'error común que casi todos cometen', 'récord increíble',
];
const ORIGENES = [
  'Japón', 'Italia', 'Reino Unido', 'Estados Unidos', 'Alemania', 'India', 'Austria', 'España', 'Latinoamérica',
  'años 50 y 60', 'años 70', 'años 80', 'años 90', 'época actual',
];

// 100 temas concretos, agrupados por categoría. Se recorren en orden intercalado
// (un tema de cada grupo por vuelta) y avanza uno por cada video del historial,
// así no se repiten hasta agotar la lista y el canal alterna entre lo que ya rinde y lo general.
const TEMAS = {
  'Yamaha MT-03: datos y verdades': [
    'Por qué la MT-03 comparte motor con la R3 y qué cambia entre las dos',
    'El motor bicilíndrico de 321 cc de la MT-03: por qué se siente más grande de lo que es',
