    'Cómo guardar la moto varias semanas sin dañarla',
    'Lavar la moto sin arruinarla: errores comunes',
    'Qué es el service de los 10 000 km y qué incluye',
  ],
  'Récords de velocidad': [
    'La moto de producción más rápida del mundo',
    'El pacto de caballeros de las 300 km/h y la Suzuki Hayabusa',
    'La moto más rápida jamás construida',
    'El récord de velocidad de las motos eléctricas',
  ],
  'Historia de marcas legendarias': [
    'Cómo una fábrica de pianos terminó haciendo motos: la historia de Yamaha',
    'Honda: de motor para bicicleta a gigante mundial',
    'KTM: de taller austríaco a campeona del Dakar',
    'Royal Enfield: la marca de motos más antigua aún en producción',
    'Kawasaki y su color verde: de la mala suerte a la identidad',
  ],
  'Motos icónicas de la historia': [
    'La Honda Super Cub: la moto más vendida de la historia',
    'La Honda CB750: la moto que inventó la superbike moderna',
    'La Yamaha RD350: la 2 tiempos que asustaba a motos más grandes',
    'La Ducati Monster: la naked que salvó a Ducati',
    'La Yamaha RX 100 y las 2 tiempos que marcaron a Latinoamérica',
  ],
  'Competición (MotoGP, Dakar, Superbike)': [
    'Cómo se inclina un piloto de MotoGP a más de 60 grados',
    'Qué es el ride height device de MotoGP',
    'El Dakar en moto: la carrera más dura del mundo',
    'Por qué las motos de MotoGP no tienen matrícula ni ABS',
  ],
  'Motor y transmisión': [
    'Por qué el cigüeñal a 270° cambia el sonido y el carácter de un bicilíndrico',
    'El embrague antirrebote (slipper clutch) explicado simple',
    'Motor refrigerado por aire vs por líquido',
    'Qué es la inyección electrónica y por qué desaparecieron los carburadores',
  ],
  'Frenos y suspensión': [
    'Horquilla invertida vs convencional: qué cambia de verdad',
    'Frenar con el freno delantero: por qué es el que más frena',
    'Cómo ajustar la precarga del amortiguador trasero',
  ],
  'Electrónica y seguridad (ABS, control de tracción)': [
    'Cómo funciona el ABS de una moto, explicado simple',
    'Control de tracción: qué hace y cuándo entra',
    'Qué es una IMU y por qué las motos modernas "saben" que están inclinadas',
  ],
  'Motos eléctricas y tecnología nueva': [
    'Motos eléctricas de entrada: ¿ya reemplazan a una de 300 cc?',
    'Cuánto cuesta cargar una moto eléctrica comparado con la gasolina',
  ],
  'Errores comunes al manejar': [
    'Mirar hacia donde quieres ir: el truco para tomar curvas',
    'El contramanillar: cómo gira de verdad una moto',
    'Por qué no se debe frenar dentro de una curva cerrada',
    'Manejar bajo lluvia: los errores que causan caídas',
  ],
};

const ORDEN = (() => {
  const grupos = Object.entries(TEMAS).map(([cat, lista]) => lista.map(tema => ({ cat, tema })));
  const out = [];
  for (let i = 0; grupos.some(g => g.length > i); i++) {
    for (const g of grupos) if (g[i]) out.push(g[i]);
  }
  return out;
})();

const rows = $input.all().map(i => i.json).filter(r => r && r.tema);
rows.sort((a, b) => new Date(a.createdAt || 0) - new Date(b.createdAt || 0));

const pick = (list, recientes) => {
  const libres = list.filter(x => !recientes.includes(x));
  const pool = libres.length ? libres : list;
  return pool[Math.floor(Math.random() * pool.length)];
};

return [{
  json: {
    fecha: new Date().toLocaleDateString('en-CA'),
    semilla: Math.floor(Math.random() * 1000000),
    // 50 % del tiempo se apunta a lo que ya rinde en el canal; el resto explora
    // el tema del día sale de la lista rotativa (uno nuevo por cada video del historial)
    categoria: ORDEN[rows.length % ORDEN.length].cat,
    tema: ORDEN[rows.length % ORDEN.length].tema,
    formato: pick(FORMATOS, rows.slice(-3).map(r => r.formato)),
    origen: pick(ORIGENES, []),
    total: rows.length,
    usadas: rows.length ? rows.map(r => r.tema).join(' | ') : '(ninguno todavía)',
  },
}];

