parameters.jsCode:
// Corta la ejecución ANTES de gastar en Kie si el tema se repite (o casi) o la salida es inservible.
const brief = $('Preparar Brief').first().json;
const out = $input.first().json.output || {};

const norm = s => String(s || '').toLowerCase()
  .normalize('NFD').replace(/[̀-ͯ]/g, '')
  .replace(/[^a-z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim();
const STOP = new Set(['de', 'la', 'el', 'los', 'las', 'un', 'una', 'y', 'en', 'del', 'que', 'por', 'con', 'para', 'a', 'al', 'vs', 'como', 'es', 'su']);
const tokens = s => new Set(norm(s).split(' ').filter(w => w.length > 2 && !STOP.has(w)));
const jaccard = (a, b) => {
  const A = tokens(a), B = tokens(b);
  if (!A.size || !B.size) return 0;
  let inter = 0;
  for (const x of A) if (B.has(x)) inter++;
  return inter / (A.size + B.size - inter);
};

if (!out.tema || !out.narracion || !out.referencia_visual || !out.referencia_escenario || !Array.isArray(out.storyboard) || out.storyboard.length !== 3) {
  throw new Error('El agente devolvió una salida incompleta (falta tema, narración, fichas, o el storyboard no tiene 3 tomas).');
}
out.storyboard.forEach((t, i) => {
  if (!t || !t.keyframe || !t.movimiento) throw new Error('La toma ' + (i + 1) + ' no tiene keyframe o movimiento.');
});

const usadas = brief.usadas === '(ninguno todavía)' ? [] : String(brief.usadas).split(' | ');
const repetida = usadas.find(u => norm(u) === norm(out.tema) || jaccard(u, out.tema) >= 0.6);
if (repetida) {
  throw new Error('Tema repetido: "' + out.tema + '" es casi igual a "' + repetida + '". No se gastó nada en Kie; vuelve a ejecutar.');
}


// La voz de Gemini habla español a ~12 caracteres/s: 250-360 caracteres = 21-30 s.
const chars = String(out.narracion).trim().length;
if (chars < 240 || chars > 390) {
  throw new Error('La narración tiene ' + chars + ' caracteres; debe tener entre 240 y 390 (el montaje acelera la voz hasta 1.25× para que entre en 28 s) (unos 46-54 palabras). No se gastó nada en Kie.');
}

// Nombre base común para todos los archivos del video: moto_2026-09-20_1100_tema
const stamp = new Date().toLocaleString('sv-SE', { hour12: false }).replace(' ', '_').replace(/:/g, '').slice(0, 15);
const slug = norm(out.tema).replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '').slice(0, 40) || 'video';
const base = 'moto_' + stamp + '_' + slug;

return $input.all().map(i => ({ json: { ...i.json, base } }));

const v = $('Validar Nuevo').first().json;
const b64 = Buffer.from(String(v.output.narracion), 'utf8').toString('base64');
return [{ json: { base: v.base, command: 'node /opt/tools/burn.js ' + v.base + ' ' + b64 } }];

const r = $input.first().json;
let out;
try { out = JSON.parse(String(r.stdout || '').trim().split('\n').pop()); }
catch (e) { throw new Error('El montaje no devolvió una respuesta válida: ' + String(r.stderr || r.stdout || '').slice(-400)); }
if (!out.ok) throw new Error('Falló el montaje: ' + out.error);
return [{ json: out }];

// Frena el workflow ANTES de gastar si la credencial de YouTube no es del canal configurado.
const esperado = String($('⚙️ Configuración').first().json.canal_youtube || '').toLowerCase().replace('@', '').trim();
const canales = $input.all().flatMap(i => i.json.items || [])
  .map(c => ({ titulo: c.snippet && c.snippet.title, handle: c.snippet && c.snippet.customUrl }));
if (!esperado) return [{ json: { canal: canales[0] || null, aviso: 'canal_youtube vacío: no se verificó' } }];
const ok = canales.some(c => String(c.handle || '').toLowerCase().replace('@', '') === esperado);
if (!ok) {
  const vistos = canales.map(c => (c.titulo || '?') + ' (' + (c.handle || 'sin handle') + ')').join(', ') || 'ninguno (¿falta la credencial?)';
  throw new Error('La credencial de YouTube no es del canal @' + esperado + '. Canal detectado: ' + vistos + '. No se gastó nada.');
}
return [{ json: { canal: canales[0] } }];

// Caption de TikTok: título + hashtags (máx. 2200 caracteres).
const o = $('Director de Cine (motos)').first().json.output;
const base = $('Validar Nuevo').first().json.base;
const caption = [o.titulo, (o.hashtags || []).join(' ') + ' #motos #moto'].join('\n\n').slice(0, 2200);
const b64 = Buffer.from(caption, 'utf8').toString('base64');
return [{ json: { base, command: 'node /opt/tools/tiktok_post.js /files/final/' + base + '_final.mp4 ' + b64 } }];

const r = $input.first().json;
let out;
try { out = JSON.parse(String(r.stdout || '').trim().split('\n').pop()); }
catch (e) { throw new Error('La publicación en TikTok no devolvió una respuesta válida: ' + String(r.stderr || r.stdout || '').slice(-400)); }
if (!out.ok) throw new Error('Falló la publicación en TikTok: ' + out.error);
return [{ json: out }];

// Storyboard de 3 tomas → un prompt CORTO por toma para Grok (Kie, texto a video).
// Grok 480p rinde mejor con 3-4 ideas claras: sujeto, encuadre, una acción y luz. Cada parte se recorta en frase completa.
const v = $('Validar Nuevo').first().json;
const o = v.output || {};
const sb = o.storyboard;
if (!Array.isArray(sb) || sb.length !== 3) throw new Error('Se esperaban 3 tomas en el storyboard, llegaron ' + (sb ? sb.length : 0));
const limpio = s => String(s || '').replace(/@\S+/g, m => m.replace('@', '')).replace(/\s+/g, ' ').trim();
// recorta a `max` caracteres sin partir frases
const corto = (s, max) => {
  s = limpio(s);
  if (s.length <= max) return s;
  const cut = s.slice(0, max);
  const fin = Math.max(cut.lastIndexOf('. '), cut.lastIndexOf('; '), cut.lastIndexOf(', '));
  return (fin > max * 0.5 ? cut.slice(0, fin + 1) : cut).trim();
};
const SOLIDEZ = 'Solid, opaque bike and rider with real mass; round wheels rolling forward; no morphing, no ghosting, no text or logos; natural engine sound only.';

return sb.map((t, i) => {
  const prompt_video = [
    `Vertical 9:16 photorealistic cinematic motorcycle film shot. ${corto(t.plano, 80)}.`,
    `Subject: ${corto(o.referencia_visual, 260)}`,
    `Frame: ${corto(t.keyframe, 320)}`,
    `Action: ${corto(t.movimiento, 260)}`,
    `Setting: ${corto(o.referencia_escenario, 220)}`,
    SOLIDEZ,
  ].join('\n');
  return { json: { base: v.base, sceneIndex: i, prompt_video } };
});

const d = $input.first().json.data || {};
const state = d.state;
if (state === 'fail') throw new Error('Kie reportó un fallo: ' + (d.failMsg || d.failCode || 'sin detalle') + ' (taskId ' + d.taskId + ')');
