// Une las 3 tomas de 10 s. De cada toma se usan los primeros 9.4 s: se descarta el final del clip,
// que es donde suelen aparecer los errores de Grok. Resultado: 3 × 9.4 s ≈ 28 s, mismo costo (30 s generados).
const base = $('Validar Nuevo').first().json.base;
const N = 3, SEG = 9.4;
const inputs = Array.from({ length: N }, (_, i) => `-i /files/${base}_${i}.mp4`).join(' ');
const cortes = Array.from({ length: N }, (_, i) => `[${i}:v]trim=0:${SEG},setpts=PTS-STARTPTS[v${i}]`).join(';');
const unir = Array.from({ length: N }, (_, i) => `[v${i}]`).join('') + `concat=n=${N}:v=1:a=0[outv]`;
const command = `/opt/tools/ffmpeg -y ${inputs} -filter_complex "${cortes};${unir}" -map "[outv]" -c:v libx264 -crf 18 -preset veryfast -an /files/${base}.mp4`;
return [{ json: { command, base } }];

